const users = $('Gebruikers ophalen').all().map(i => i.json).filter(u => u && u.session_id && u.email);
const logs = $input.all().map(i => i.json).filter(l => l && l.session_id);
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Amsterdam' }));
const first = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const pad = n => String(n).padStart(2, '0');
const maandPrefix = first.getFullYear() + '-' + pad(first.getMonth() + 1);
const MND = {
  nl: ['januari','februari','maart','april','mei','juni','juli','augustus','september','oktober','november','december'],
  en: ['January','February','March','April','May','June','July','August','September','October','November','December'],
  tr: ['Ocak','Subat','Mart','Nisan','Mayis','Haziran','Temmuz','Agustos','Eylul','Ekim','Kasim','Aralik'],
  ar: ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر']
};
const TAALNAAM = { nl: 'Nederlands', en: 'English', tr: 'Turkish', ar: 'Arabic' };
const out = [];
for (const u of users) {
  if (u.onboarding_complete !== true && u.onboarding_complete !== 'true') { continue; }
  const lang = MND[u.language] ? u.language : 'nl';
  const maandNaam = MND[lang][first.getMonth()] + ' ' + first.getFullYear();
  const mine = logs.filter(l => l.session_id === u.session_id && String(l.log_date || '').slice(0, 7) === maandPrefix);
  if (mine.length === 0) { continue; }
  const ochtend = mine.filter(l => l.period === 'ochtend');
  const avond = mine.filter(l => l.period === 'avond');
  const berichten = mine.filter(l => l.period === 'bericht');
  const scores = ochtend.map(l => parseInt(l.wellbeing, 10)).filter(n => !isNaN(n));
  const gem = scores.length ? (scores.reduce((a, b) => a + b, 0) / scores.length) : null;
  const medJa = avond.filter(l => l.medication_taken === 'ja').length;
  const medNee = avond.filter(l => l.medication_taken === 'nee').length;
  const aandacht = mine.filter(l => l.concern_level === 'AANDACHT' || l.concern_level === 'URGENT').length;
  const laagsteDagen = ochtend.filter(l => parseInt(l.wellbeing, 10) <= 2).map(l => l.log_date);
  const berichtTeksten = berichten.slice(-15).map(l => l.log_date + ': ' + String(l.symptoms || '').slice(0, 200));
  const feiten = [
    'WRITE YOUR ANSWER IN THIS LANGUAGE: ' + TAALNAAM[lang],
    'Month: ' + maandNaam,
    'Name: ' + (u.name || 'unknown'),
    'Morning check-ins: ' + ochtend.length,
    'Average wellbeing (1 = bad, 5 = good): ' + (gem === null ? 'no data' : gem.toFixed(1)),
    'Days scoring 1 or 2: ' + (laagsteDagen.length ? laagsteDagen.join(', ') : 'none'),
    'Evening check-ins: ' + avond.length,
    'Medication taken: ' + medJa + ' times yes, ' + medNee + ' times no',
    'Moments needing attention: ' + aandacht,
    'Own messages: ' + (berichtTeksten.length ? berichtTeksten.join(' | ') : 'none')
  ].join('\n');
  out.push({ json: {
    session_id: u.session_id,
    email: u.email,
    name: u.name || '',
    lang: lang,
    maand: maandNaam,
    gemiddelde: gem === null ? '' : gem.toFixed(1),
    ochtend_aantal: ochtend.length,
    avond_aantal: avond.length,
    med_ja: medJa,
    med_nee: medNee,
    aandacht: aandacht,
    feiten: feiten
  } });
}
return out;

const stats = $('Maandcijfers berekenen').item.json;
const ai = $input.first().json || {};
const lang = stats.lang || 'nl';
const L = {
  nl: { hi: 'Beste', subj: 'Uw CareFlow-overzicht van ', head: 'Uw cijfers van ', m: 'Ochtend-checks', a: 'Avond-checks', w: 'Gemiddeld welbevinden', scale: '(1 = slecht, 5 = goed)', med: 'Medicijnen ingenomen', yes: 'keer ja', no: 'keer nee', att: 'Momenten met extra aandacht', none: 'geen gegevens', fb: 'Hieronder vindt u uw cijfers van afgelopen maand.', disc: 'Dit overzicht is automatisch gemaakt door CareFlow, een studentenproject. Het is geen medisch advies. Bespreek zorgen altijd met uw huisarts. Bel bij nood zelf 112.' },
  en: { hi: 'Dear', subj: 'Your CareFlow overview for ', head: 'Your figures for ', m: 'Morning check-ins', a: 'Evening check-ins', w: 'Average wellbeing', scale: '(1 = bad, 5 = good)', med: 'Medication taken', yes: 'times yes', no: 'times no', att: 'Moments needing attention', none: 'no data', fb: 'Below are your figures for last month.', disc: 'This overview was generated automatically by CareFlow, a student project. It is not medical advice. Always discuss concerns with your doctor. In an emergency, call 112 yourself.' },
  tr: { hi: 'Sayin', subj: 'CareFlow ozetiniz: ', head: 'Rakamlariniz: ', m: 'Sabah kontrolleri', a: 'Aksam kontrolleri', w: 'Ortalama iyilik hali', scale: '(1 = kotu, 5 = iyi)', med: 'Ilac alindi', yes: 'kez evet', no: 'kez hayir', att: 'Dikkat gerektiren anlar', none: 'veri yok', fb: 'Asagida gecen aya ait rakamlariniz yer aliyor.', disc: 'Bu ozet, bir ogrenci projesi olan CareFlow tarafindan otomatik olusturulmustur. Tibbi tavsiye degildir. Endiselerinizi mutlaka doktorunuzla gorusun. Acil durumda 112 yi kendiniz arayin.' },
  ar: { hi: 'عزيزي', subj: 'ملخص CareFlow لشهر ', head: 'أرقامك لشهر ', m: 'فحوصات الصباح', a: 'فحوصات المساء', w: 'متوسط الشعور بالراحة', scale: '(1 = سيء، 5 = جيد)', med: 'تناول الدواء', yes: 'مرة نعم', no: 'مرة لا', att: 'لحظات تحتاج انتباها', none: 'لا توجد بيانات', fb: 'فيما يلي أرقامك للشهر الماضي.', disc: 'تم إنشاء هذا الملخص تلقائيا بواسطة CareFlow، وهو مشروع طلابي. ليس هذا نصيحة طبية. ناقش أي قلق مع طبيبك دائما. في حالة الطوارئ اتصل بالرقم 112 بنفسك.' }
};
const x = L[lang] || L.nl;
let tekst = '';
if (typeof ai.content === 'string') { tekst = ai.content; }
else if (ai.message && typeof ai.message.content === 'string') { tekst = ai.message.content; }
else if (typeof ai.text === 'string') { tekst = ai.text; }
tekst = String(tekst || '').trim();
if (!tekst) { tekst = x.fb; }
const cijfers = x.head + stats.maand + ':\n' +
  '- ' + x.m + ': ' + stats.ochtend_aantal + '\n' +
  '- ' + x.a + ': ' + stats.avond_aantal + '\n' +
  '- ' + x.w + ': ' + (stats.gemiddelde || x.none) + ' ' + x.scale + '\n' +
  '- ' + x.med + ': ' + stats.med_ja + ' ' + x.yes + ', ' + stats.med_nee + ' ' + x.no + '\n' +
  '- ' + x.att + ': ' + stats.aandacht;
const body = x.hi + ' ' + (stats.name || '') + ',\n\n' + tekst + '\n\n' + cijfers + '\n\n' + x.disc;
return [{ json: { email: stats.email, subject: x.subj + stats.maand, body: body } }];
